import fetch from '@common/fetch'
const urlPrefix = '/api/'
export default {

  getRoute(params) {
    return fetch({
      url: urlPrefix + 'route/auth',
      method: 'get',
      params,
    })
  },

  getUiPermission(params) {
    return fetch({
      url: urlPrefix + 'permission/ui/auth',
      method: 'get',
      params,
    })
  },

  startGame (params) {
    return fetch({
      url: urlPrefix + 'game/start/auth',
      method: 'post',
      data: params,
      timeout: 70000,
    })
  },

  getGameInfo (params) {
    return fetch({
      url: urlPrefix + 'game/info/auth',
      method: 'get',
      params,
    })
  },

  nextStage (params) {
    return fetch({
      url: urlPrefix + 'game/nextStage/auth',
      method: 'get',
      params,
    })
  },

  userNextStage (params) {
    return fetch({
      url: urlPrefix + 'game/userNextStage/auth',
      method: 'get',
      params,
    })
  },

  gameRecord (params) {
    return fetch({
      url: urlPrefix + 'game/record/auth',
      method: 'get',
      params,
    })
  },

  checkPlayerRole (params) {
    return fetch({
      url: urlPrefix + 'game/checkPlayer/auth',
      method: 'get',
      params,
    })
  },

  assaultPlayer (params) {
    return fetch({
      url: urlPrefix + 'game/assaultPlayer/auth',
      method: 'get',
      params,
    })
  },

  wolfSuggestions (params) {
    return fetch({
      url: urlPrefix + 'game/wolfSuggestions/auth',
      method: 'get',
      params,
      overHandle: true,
    })
  },

  antidotePlayer (params) {
    return fetch({
      url: urlPrefix + 'game/antidotePlayer/auth',
      method: 'get',
      params,
    })
  },

  votePlayer (params) {
    return fetch({
      url: urlPrefix + 'game/votePlayer/auth',
      method: 'get',
      params,
    })
  },

  poisonPlayerRole (params) {
    return fetch({
      url: urlPrefix + 'game/poisonPlayer/auth',
      method: 'get',
      params,
    })
  },

  shootPlayerRole (params) {
    return fetch({
      url: urlPrefix + 'game/shootPlayer/auth',
      method: 'get',
      params,
    })
  },

  boomAction (params) {
    return fetch({
      url: urlPrefix + 'game/boomPlayer/auth',
      method: 'get',
      params,
    })
  },

  gameResult (params) {
    return fetch({
      url: urlPrefix + 'game/result/auth',
      method: 'get',
      params,
    })
  },

  gameDestroy (params) {
    return fetch({
      url: urlPrefix + 'game/destroy/auth',
      method: 'get',
      params,
    })
  },

  saveLastWords (params) {
    return fetch({
      url: urlPrefix + 'game/saveLastWords/auth',
      method: 'post',
      data: params,
    })
  },

  gameAgain  (params) {
    return fetch({
      url: urlPrefix + 'game/again/auth',
      method: 'get',
      params,
    })
  },
}
